package com.danesh.bp.mac

import com.danesh.bp.key.BpKeyConfig
import com.danesh.bp.key.decodeHexKey
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Test

class AnsiX919MacTest {

    @Test
    fun initSample_matchesHostExpectedMac_with24ByteInitialKey() {
        val key = BpKeyConfig.INITIAL_MASTER_KEY_HEX.decodeHexKey()
        assertEquals(24, key.size)

        // ISO body without TPDU/length bitmap bit 64 set, F64 bytes excluded (packForMac semantics).
        val macInput = MAC_INPUT_HEX.decodeHexKey()
        assertEquals(473, macInput.size)
        assertEquals(0x0F.toByte(), macInput[9]) // primary bitmap last byte: bit 64 set

        val mac = AnsiX919Mac.calculate(key, macInput)
        assertArrayEquals(EXPECTED_MAC_HEX.decodeHexKey(), mac)
    }

    @Test
    fun centermInitSample_matchesHostExpectedMac() {
        val key = BpKeyConfig.INITIAL_MASTER_KEY_HEX.decodeHexKey()
        val macInput = CENTERM_INIT_MAC_INPUT_HEX.decodeHexKey()
        assertEquals(497, macInput.size)
        assertEquals(0x0F.toByte(), macInput[9]) // bitmap bit 64 set, F64 bytes excluded

        val mac = AnsiX919Mac.calculate(key, macInput)
        assertArrayEquals(CENTERM_INIT_EXPECTED_MAC_HEX.decodeHexKey(), mac)
    }

    @Test
    fun truncated16ByteKey_doesNotMatchHostVector() {
        val key24 = BpKeyConfig.INITIAL_MASTER_KEY_HEX.decodeHexKey()
        val key16 = key24.copyOf(16)
        val macInput = MAC_INPUT_HEX.decodeHexKey()
        val mac16 = AnsiX919Mac.calculate(key16, macInput)
        assertEquals(false, mac16.contentEquals(EXPECTED_MAC_HEX.decodeHexKey()))
    }

    @Test
    fun method2Padding_differsFromZeroPad_whenInputNotAligned() {
        val key = BpKeyConfig.INITIAL_MASTER_KEY_HEX.decodeHexKey()
        val macInput = CENTERM_INIT_MAC_INPUT_HEX.decodeHexKey()
        assertEquals(1, macInput.size % 8) // padding mode must change the MAC
        val zero = AnsiX919Mac.calculate(key, macInput, AnsiX919Mac.Padding.ZERO)
        val method2 = AnsiX919Mac.calculate(key, macInput, AnsiX919Mac.Padding.ISO9797_METHOD2)
        assertEquals(false, zero.contentEquals(method2))
    }

    companion object {
        private const val CENTERM_INIT_EXPECTED_MAC_HEX = "D818377B026F297F"

        /** Init MAC input (497 B) — bitmap bit 64 on, F64 omitted Centerm capture Jul 2026. */
        private const val CENTERM_INIT_MAC_INPUT_HEX =
            ""

        private const val EXPECTED_MAC_HEX = "204DD034A61C91C1"

        /**
         * Captured init MAC input (473 bytes): length+TPDU stripped, bitmap bit 64 set, F64 bytes omitted.
         */
        private const val MAC_INPUT_HEX =
            ""
    }
}
